arguments.command:
cd /workspace && grep -n "allowed(\|claim_identity\|def hosted\|_tag\b" submission/gateway.py; python3 - <<'PYEOF'
import ast, sys
src=open('/workspace/submission/gateway.py').read()
tree=ast.parse(src)
defined=set()
for node in ast.walk(tree):
    if isinstance(node,(ast.FunctionDef,ast.ClassDef)): defined.add(node.name)
used=set()
for node in ast.walk(tree):
    if isinstance(node,ast.Name): used.add(node.id)
    if isinstance(node,ast.Attribute): used.add(node.attr)
print("possibly unused defs:", sorted(d for d in defined if d not in used))
# module level constants unused
consts=[t.name for n in tree.body if isinstance(n,ast.Assign) for t in n.targets if isinstance(t,ast.Name)]
print("possibly unused consts:", [c for c in consts if src.count(c)<2])
PYEOF
